import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

max_reduce_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <float.h>
#include <vector>

__global__ void max_reduce_kernel(const float* __restrict__ input,
                                   float* __restrict__ output,
                                   long outer_size,
                                   long reduce_size,
                                   long inner_size) {
    extern __shared__ float sdata[];
    long outer_idx = blockIdx.y;
    if (outer_idx >= outer_size) return;
    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int bx = blockDim.x;
    int by = blockDim.y;
    long inner_idx_start = blockIdx.x * (long)bx + tx;
    long stride_inner = (long)bx * gridDim.x;
    for (long inner_idx = inner_idx_start; inner_idx < inner_size; inner_idx += stride_inner) {
        const float* base = input + outer_idx * reduce_size * inner_size + inner_idx;
        float max_val = -FLT_MAX;
        for (long i = ty; i < reduce_size; i += by) {
            float val = __ldg(&base[i * inner_size]);
            max_val = fmaxf(max_val, val);
        }
        int sidx = ty * bx + tx;
        sdata[sidx] = max_val;
        __syncthreads();
        for (int s = by / 2; s > 0; s >>= 1) {
            if (ty < s) {
                sdata[sidx] = fmaxf(sdata[sidx], sdata[sidx + s * bx]);
            }
            __syncthreads();
        }
        if (ty == 0) {
            output[outer_idx * inner_size + inner_idx] = sdata[tx];
        }
        __syncthreads();
    }
}
torch::Tensor max_reduce_cuda(torch::Tensor input, int64_t dim) {
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(input.scalar_type() == torch::kFloat32, "input must be float32");
    TORCH_CHECK(input.is_contiguous(), "input must be contiguous");
    int ndim = input.dim();
    if (dim < 0) dim += ndim;
    TORCH_CHECK(dim >= 0 && dim < ndim, "dim out of range");
    auto sizes = input.sizes();
    long outer_size = 1;
    for (int i = 0; i < dim; ++i) outer_size *= sizes[i];
    long reduce_size = sizes[dim];
    long inner_size = 1;
    for (int i = dim + 1; i < ndim; ++i) inner_size *= sizes[i];
    std::vector<int64_t> out_sizes;
    for (int i = 0; i < ndim; ++i) {
        if (i != dim) out_sizes.push_back(sizes[i]);
    }
    auto output = torch::empty(out_sizes, input.options());
    int threads_x = 32;
    int threads_y = 8;
    dim3 block(threads_x, threads_y);
    long blocks_x_l = (inner_size + threads_x - 1) / threads_x;
    int blocks_x = (int)(blocks_x_l > 65535 ? 65535 : blocks_x_l);
    if (blocks_x < 1) blocks_x = 1;
    int blocks_y = (int)(outer_size > 65535 ? 65535 : outer_size);
    if (blocks_y < 1) blocks_y = 1;
    dim3 grid(blocks_x, blocks_y);
    size_t shared_bytes = (size_t)threads_x * threads_y * sizeof(float);
    max_reduce_kernel<<<grid, block, shared_bytes>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        outer_size, reduce_size, inner_size
    );
    return output;
}
"""

max_reduce_cpp_source = "torch::Tensor max_reduce_cuda(torch::Tensor input, int64_t dim);"

max_reduce_module = load_inline(
    name="max_reduce_module",
    cpp_sources=max_reduce_cpp_source,
    cuda_sources=max_reduce_source,
    functions=["max_reduce_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Optimized model that performs Max reduction over a specific dimension
    using a custom CUDA kernel.
    """
    def __init__(self, dim: int):
        super(ModelNew, self).__init__()
        self.dim = dim
        self.max_reduce = max_reduce_module

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.cuda().contiguous()
        return self.max_reduce.max_reduce_cuda(x, self.dim)


